    const allocation = allocateDayMountains(insights, options.strategyMode, options.maxMountainsPerDay, options.customUserPrompt);
    const pinnedComboNote = (db.optimizationNotes || []).find((n) => n.isPinned || n.category === 'COMBO_TIME_SAVER');
