    ctx.fillStyle = '#B8B4A9';
    ctx.font = '12px "JetBrains Mono", monospace';
    ctx.fillText('THỜI GIAN CÒN LẠI TRÊN NÚI:', 92, 235);
    ctx.fillStyle = '#F6F4EE';
    ctx.font = 'bold 28px "JetBrains Mono", monospace';
